using Godot;
using System;
using Settings = Godot.Collections.Dictionary;

public partial class ModelWorkspaceOperations
{
    public Button button(Node parent, string text, RefCounted action, string tooltip)
    { var result = AddButton(parent, text, () => action.Call("invoke_no_args")); result.TooltipText = tooltip; result.TreeExiting += () => action.Call("release"); return result; }
    public void label(Node parent, string text) => Label(parent, text);
    public void clear(Node parent) => Clear(parent);
    public void separator(Node parent) => parent.AddChild(new VSeparator());
    public void draw(Control workspace) => workspace.DrawRect(new Rect2(Vector2.Zero, workspace.Size), new Color("101923"));
    public void setup(Control workspace)
    {
        workspace.Set("rig_ui", GD.Load<GDScript>("res://Workspaces/ModelWorkspace/rig/rig_ui.gd").New(workspace)); workspace.SetAnchorsAndOffsetsPreset(Control.LayoutPreset.FullRect); workspace.Call("_build_theme"); workspace.AddThemeFontSizeOverride("font_size", 13);
        var column = new VBoxContainer(); column.SetAnchorsAndOffsetsPreset(Control.LayoutPreset.FullRect); column.AddThemeConstantOverride("separation", 5); workspace.AddChild(column); var header = new HBoxContainer(); column.AddChild(header); var title = workspace.Get("title").As<Label>(); title.Text = "3D MODEL  /  Untitled"; title.SizeFlagsHorizontal = Control.SizeFlags.ExpandFill; title.AddThemeColorOverride("font_color", new Color("79dfc5")); header.AddChild(title);
        var file = new MenuButton { Text = "File" }; header.AddChild(file); foreach (string text in new[] { "Open model / import…", "Save   Ctrl+S", "Save As…   Ctrl+Shift+S", "Save to Super Clipboard" }) file.GetPopup().AddItem(text);
        file.GetPopup().IdPressed += id => { switch (id) { case 0: workspace.Call("open_dialog"); break; case 1: workspace.Call("save"); break; case 2: workspace.Call("save_as"); break; case 3: workspace.GetTree().Root.GetNodeOrNull<Node>("SuperClipboard")?.Call("quick_save", Session(workspace).Get("document").As<Resource>().Call("snapshot"), title.Text, "default"); break; } };
        AddButton(header, "↶", () => Session(workspace).Call("undo")).TooltipText = "Undo · Ctrl+Z"; AddButton(header, "↷", () => Session(workspace).Call("redo")).TooltipText = "Redo · Ctrl+Shift+Z"; AddButton(header, "⌕ Commands", () => workspace.Call("command_search")).TooltipText = "Search all tools · Space"; AddButton(header, "✦ Quick Rig", () => workspace.Get("rig_ui").As<RefCounted>().Call("quick_rig")).TooltipText = "Create bones → Bind geometry → Pose"; AddButton(header, "To Scene ↗", () => workspace.Call("_to_scene_after_save")).TooltipText = "Save and create a Basic Mesh actor";
        var tools = new HBoxContainer(); column.AddChild(tools); var modes = workspace.Get("mode_buttons").AsGodotDictionary();
        foreach (string mode in new[] { "Object", "Vertex", "Edge", "Face" }) { var modeButton = AddButton(tools, mode, () => { var session = Session(workspace); session.Set("mode", mode); session.Set("elements", Array.Empty<int>()); session.EmitSignal("changed"); }); modeButton.TooltipText = "Selection mode · " + (modes.Count + 1); modeButton.ToggleMode = true; modes[mode] = modeButton; }
        tools.AddChild(new VSeparator()); AddButton(tools, "＋ Create", () => workspace.Call("create_menu")); var canvas = workspace.Get("canvas").As<Control>(); var toolButtons = workspace.Get("_tool_buttons").AsGodotDictionary();
        foreach (string name in new[] { "Move", "Rotate", "Scale" }) { var tool = AddButton(tools, name, () => { canvas.Set("tool", name); canvas.Set("sculpt", ""); canvas.Get("overlay").As<Control>().QueueRedraw(); workspace.Set("_refresh_pending", true); }); tool.TooltipText = name == "Move" ? "W" : name == "Rotate" ? "E" : "R"; tool.ToggleMode = true; toolButtons[name] = tool; }
        var space = new OptionButton(); space.AddItem("World axes"); space.AddItem("Local axes"); tools.AddChild(space); space.ItemSelected += index => { canvas.Set("local_axes", index == 1); canvas.Get("overlay").As<Control>().QueueRedraw(); }; workspace.Set("_space_picker", space);
        var snap = new CheckButton { Text = "Snap" }; tools.AddChild(snap); snap.Toggled += next => canvas.Set("snap", next); workspace.Set("_snap_button", snap); var view = new MenuButton { Text = "View ▾" }; tools.AddChild(view); foreach (string text in new[] { "Frame selected · F", "Frame all · Shift+F", "Perspective / orthographic", "Front", "Back", "Left", "Right", "Top", "Bottom", "Grid", "Edges", "Wireframe", "X-ray", "Face normals", "Components panel", "Properties panel" }) view.GetPopup().AddItem(text); view.GetPopup().Connect(PopupMenu.SignalName.IdPressed, new Callable(workspace, "_view_command"));
        var contextScroll = new ScrollContainer { CustomMinimumSize = new Vector2(0, 34), VerticalScrollMode = ScrollContainer.ScrollMode.Disabled }; column.AddChild(contextScroll); contextScroll.AddChild(workspace.Get("context").As<Node>()); var split = new HSplitContainer { SizeFlagsVertical = Control.SizeFlags.ExpandFill }; column.AddChild(split); workspace.Set("_left_split", split);
        var hierarchy = workspace.Get("hierarchy").As<ModelHierarchy>(); hierarchy.Name = "ModelComponents"; hierarchy.CustomMinimumSize = new Vector2(150, 0); hierarchy.SizeFlagsVertical = Control.SizeFlags.ExpandFill; hierarchy.HideRoot = true; hierarchy.Columns = 3; foreach (int i in new[] { 1, 2 }) { hierarchy.SetColumnExpand(i, false); hierarchy.SetColumnCustomMinimumWidth(i, 26); } hierarchy.SelectMode = Tree.SelectModeEnum.Multi; hierarchy.AllowReselect = true; split.AddChild(hierarchy); hierarchy.Connect(Tree.SignalName.MultiSelected, new Callable(workspace, "_tree_selected")); hierarchy.Connect(Tree.SignalName.ItemEdited, new Callable(workspace, "_rename")); hierarchy.Connect(Tree.SignalName.ButtonClicked, new Callable(workspace, "_tree_button")); hierarchy.session = Session(workspace); hierarchy.TooltipText = "Drag onto a component to parent. Drop in empty space to unparent. World position is preserved.";
        var main = new HSplitContainer { SizeFlagsHorizontal = Control.SizeFlags.ExpandFill }; split.AddChild(main); workspace.Set("_main_split", main); canvas.Set("session", Session(workspace)); canvas.SizeFlagsHorizontal = Control.SizeFlags.ExpandFill; canvas.SizeFlagsVertical = Control.SizeFlags.ExpandFill; main.AddChild(canvas); canvas.Connect("command_requested", new Callable(workspace, "run_command")); canvas.Connect("gesture_finished", new Callable(workspace, "_refresh")); canvas.Connect("notice", Callable.From<string>(message => Status(workspace, message)));
        var tabs = workspace.Get("_inspector_tabs").As<TabContainer>(); tabs.CustomMinimumSize = new Vector2(235, 0); main.AddChild(tabs); foreach (var (name, field) in new[] { ("Object", "properties"), ("Modifiers", "_modifiers"), ("Surface", "_surfaces") }) { var scroll = new ScrollContainer { Name = name, HorizontalScrollMode = ScrollContainer.ScrollMode.Disabled }; tabs.AddChild(scroll); var fields = workspace.Get(field).As<VBoxContainer>(); fields.SizeFlagsHorizontal = Control.SizeFlags.ExpandFill; fields.AddThemeConstantOverride("separation", 8); scroll.AddChild(fields); }
        var status = workspace.Get("status").As<Label>(); status.CustomMinimumSize = new Vector2(0, 22); status.TextOverrunBehavior = TextServer.OverrunBehavior.TrimEllipsis; status.AddThemeColorOverride("font_color", new Color("96adbd")); column.AddChild(status); split.SplitOffsets = new[] { 180 }; main.SplitOffsets = new[] { 950 }; Session(workspace).Connect("changed", new Callable(workspace, "_changed")); workspace.Call("_refresh"); new Callable(workspace, "_initial_layout").CallDeferred();
    }
    private static int Offset(HSplitContainer split) { var values = split.SplitOffsets; return values.Length > 0 ? values[0] : 0; }
    public void initial_layout(Control workspace)
    {
        var pending = workspace.Get("_pending_panels").AsGodotDictionary(); if (pending.Count > 0) { workspace.Call("_restore_panels", pending); workspace.Set("_pending_panels", new Settings()); }
        else { workspace.Get("_left_split").As<HSplitContainer>().SplitOffsets = new[] { Mathf.Clamp((int)(workspace.Size.X * .13f), 150, 200) }; var main = workspace.Get("_main_split").As<HSplitContainer>(); main.SplitOffsets = new[] { Math.Max(250, (int)main.Size.X - 280) }; if (workspace.Size.X < 1100) workspace.Get("hierarchy").As<Control>().Hide(); } workspace.Set("_layout_ready", true);
    }
    public Settings capture_panels(Control workspace) => new() { ["hierarchy"] = workspace.Get("hierarchy").As<Control>().Visible, ["inspector"] = workspace.Get("_inspector_tabs").As<Control>().Visible, ["inspector_tab"] = workspace.Get("_inspector_tabs").As<TabContainer>().CurrentTab, ["left"] = Offset(workspace.Get("_left_split").As<HSplitContainer>()), ["right"] = Offset(workspace.Get("_main_split").As<HSplitContainer>()) };
    public void restore_panels(Control workspace, Settings state)
    {
        workspace.Get("hierarchy").As<Control>().Visible = state.TryGetValue("hierarchy", out var hierarchy) ? hierarchy.AsBool() : workspace.Size.X >= 1100; var tabs = workspace.Get("_inspector_tabs").As<TabContainer>(); tabs.Visible = !state.TryGetValue("inspector", out var inspector) || inspector.AsBool(); tabs.CurrentTab = Mathf.Clamp(state.TryGetValue("inspector_tab", out var tab) ? tab.AsInt32() : 0, 0, 2); workspace.Get("_left_split").As<HSplitContainer>().SplitOffsets = new[] { state.TryGetValue("left", out var left) ? left.AsInt32() : 180 }; var main = workspace.Get("_main_split").As<HSplitContainer>(); main.SplitOffsets = new[] { state.TryGetValue("right", out var right) ? right.AsInt32() : Math.Max(250, (int)main.Size.X - 280) };
    }
    public void build_theme(Control workspace)
    {
        var theme = new Theme { DefaultFontSize = 13 }; workspace.Theme = theme; foreach (string type in new[] { "Button", "MenuButton", "OptionButton", "CheckButton", "Label", "LineEdit", "Tree", "TabContainer", "PopupMenu" }) theme.SetFontSize("font_size", type, 13);
        foreach (var (name, background, border) in new[] { ("normal", "182b3a", "344e60"), ("hover", "24473f", "72d6bc"), ("pressed", "285b51", "79e3c5"), ("focus", "182b3a", "73d9c0"), ("disabled", "17232e", "283744") }) { var style = new StyleBoxFlat { BgColor = new Color(background), BorderColor = new Color(border), ContentMarginLeft = 9, ContentMarginRight = 9, ContentMarginTop = 5, ContentMarginBottom = 5 }; style.SetBorderWidthAll(1); style.SetCornerRadiusAll(6); foreach (string type in new[] { "Button", "OptionButton", "MenuButton" }) theme.SetStylebox(name, type, style); }
        var panel = new StyleBoxFlat { BgColor = new Color("14222e"), BorderColor = new Color("31495a"), ContentMarginLeft = 8, ContentMarginRight = 8, ContentMarginTop = 7, ContentMarginBottom = 7 }; panel.SetBorderWidthAll(1); panel.SetCornerRadiusAll(7); theme.SetStylebox("panel", "Tree", panel); theme.SetStylebox("panel", "TabContainer", panel); var selected = (StyleBoxFlat)panel.Duplicate(); selected.BgColor = new Color("26564d"); selected.BorderColor = new Color("78dbc2"); theme.SetStylebox("selected", "Tree", selected); theme.SetStylebox("selected_focus", "Tree", selected); var field = (StyleBoxFlat)panel.Duplicate(); field.BgColor = new Color("0f1d29"); field.ContentMarginTop = 4; field.ContentMarginBottom = 4; theme.SetStylebox("normal", "LineEdit", field); theme.SetColor("font_color", "LineEdit", new Color("e4eef5")); foreach (string name in new[] { "tab_selected", "tab_unselected", "tab_hovered" }) { var tab = (StyleBoxFlat)panel.Duplicate(); tab.BgColor = new Color(name == "tab_selected" ? "26534b" : "192d3c"); theme.SetStylebox(name, "TabContainer", tab); }
    }
}
